WITH valid AS (SELECT *, CASE WHEN country = 'JP' THEN 1 ELSE 0 END AS is_jp, COALESCE(country, 'N/A') AS resolved_country FROM sessions WHERE country IS NOT NULL AND country = 'TH'), flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM valid), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, CASE WHEN is_new_session >= 1 THEN 'HIGH' ELSE 'LOW' END AS is_new_session_tier, APPROX_PERCENTILE(is_jp, 0.5) AS is_jp_p50, COUNT(*) FILTER (WHERE country = 'UK') AS uk_rows, COUNT(DISTINCT country) AS distinct_countries, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM sessionized GROUP BY ROLLUP (DATE_TRUNC('YEAR', started_at), CASE WHEN is_new_session >= 1 THEN 'HIGH' ELSE 'LOW' END) HAVING distinct_customer_ids > 1;
